from taf.hw.hp.redfish.httpclient.ApiClient import ApiClient
from taf.hw.hp.redfish.httpclient.redfish_uri import RootURI


class RootCommon(object):
    def __init__(self, configuration, access_token):
        self.httpclient = ApiClient(configuration, access_token)

    def get_service_root_info(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = RootURI().service_root_uri + uri_params
        return self.httpclient.send_get_request(uri=uri, check_status=check_status)
